<?php
defined('ABSPATH') || exit;
function robw_oauth_json($value,$status=200){status_header($status);header('Content-Type: application/json');header('Cache-Control: no-store');header('Pragma: no-cache');header('X-Content-Type-Options: nosniff');echo wp_json_encode($value);exit;}
function robw_oauth_error($code,$status=400){robw_oauth_json(['error'=>$code],$status);}
function robw_oauth_validate_pairs($raw){$seen=[];foreach(explode('&',$raw)as$pair){if($pair==='')continue;$key=urldecode(explode('=',$pair,2)[0]);if(isset($seen[$key])||str_contains($key,'[')||preg_match('/[^a-zA-Z0-9_]/',$key))robw_oauth_error('invalid_request');$seen[$key]=true;}}
function robw_oauth_route(){ $path=wp_parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$base=rtrim(wp_parse_url(home_url(),PHP_URL_PATH)??'','/');$route=substr($path,strlen($base));if(!str_starts_with($route,'/robw-oauth/')&&$route!=='/.well-known/oauth-authorization-server')return;
 $local=defined('ROBW_OAUTH_LOCAL_TEST')&&ROBW_OAUTH_LOCAL_TEST&&in_array(wp_parse_url(home_url(),PHP_URL_HOST),['127.0.0.1','localhost'],true);if(!is_ssl()&&!$local)robw_oauth_error('https_required',400);
 header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');if(strlen($_SERVER['QUERY_STRING']??'')>8192||(int)($_SERVER['CONTENT_LENGTH']??0)>16384)robw_oauth_error('invalid_request');robw_oauth_validate_pairs($_SERVER['QUERY_STRING']??'');if($_SERVER['REQUEST_METHOD']==='POST'){if(!str_starts_with(strtolower($_SERVER['CONTENT_TYPE']??''),'application/x-www-form-urlencoded'))robw_oauth_error('invalid_request');$body=file_get_contents('php://input',false,null,0,16385);if(strlen($body)>16384)robw_oauth_error('invalid_request');robw_oauth_validate_pairs($body);}$_GET=wp_unslash($_GET);$_POST=wp_unslash($_POST);foreach(array_merge($_GET,$_POST)as$v)if(!is_string($v))robw_oauth_error('invalid_request');
 try{
 if($route==='/.well-known/oauth-authorization-server'){if($_SERVER['REQUEST_METHOD']!=='GET')robw_oauth_error('invalid_request',405);$url=home_url('/robw-oauth/');robw_oauth_json(['issuer'=>home_url(),'authorization_endpoint'=>$url.'authorize','token_endpoint'=>$url.'token','revocation_endpoint'=>$url.'revoke','response_types_supported'=>['code'],'grant_types_supported'=>['authorization_code','refresh_token'],'token_endpoint_auth_methods_supported'=>['none'],'code_challenge_methods_supported'=>['S256'],'scopes_supported'=>['repo:read','repo:write']]);}
 if($route==='/robw-oauth/authorize'){robw_oauth_authorize();}
 if($route==='/robw-oauth/token'){if($_SERVER['REQUEST_METHOD']!=='POST'||$_GET)robw_oauth_error('invalid_request',405);$store=new RobwOAuthStore();$server=robw_oauth_server($store);$req=RobwOAuthVendor\OAuth2\Request::createFromGlobals();$res=new RobwOAuthVendor\OAuth2\Response();$server->handleTokenRequest($req,$res);$res->send();exit;}
 if($route==='/robw-oauth/revoke'){if($_SERVER['REQUEST_METHOD']!=='POST'||$_GET)robw_oauth_error('invalid_request',405);$client=$_POST['client_id']??'';$token=$_POST['token']??'';if($token==='')robw_oauth_error('invalid_request');[$raw,$s]=RobwOAuthDB::read();if(!isset($s['clients'][$client]))robw_oauth_error('invalid_client',401);$hint=$_POST['token_type_hint']??'';if(!in_array($hint,['','access_token','refresh_token'],true))robw_oauth_error('unsupported_token_type');foreach(['access','refresh']as$kind){$r=$s[$kind][RobwOAuthDB::key($token)]??null;if($r&&$r['client_id']===$client)RobwOAuthDB::revoke($r['family']);}robw_oauth_json(new stdClass());}
 if($route==='/robw-oauth/resource'){if(!in_array($_SERVER['REQUEST_METHOD'],['GET','POST'],true))robw_oauth_error('invalid_request',405);$repo=$_GET['repo']??'';$r=robw_oauth_principal($_SERVER['HTTP_AUTHORIZATION']??'', $repo,$_SERVER['REQUEST_METHOD']==='POST');if(is_wp_error($r)){if(str_starts_with(strtolower($_SERVER['HTTP_AUTHORIZATION']??''),'bearer ')){header('WWW-Authenticate: Bearer realm="Git OAuth", error="'.$r->get_error_code().'"');}elseif($r->get_error_data()['status']===401)header('WWW-Authenticate: Basic realm="Git OAuth"');robw_oauth_json(['error'=>$r->get_error_code()],$r->get_error_data()['status']);}robw_oauth_json($r);}
 robw_oauth_error('not_found',404);
 }catch(InvalidArgumentException $e){robw_oauth_error('invalid_grant');}catch(Throwable $e){if(defined('ROBW_OAUTH_LOCAL_TEST')&&ROBW_OAUTH_LOCAL_TEST)robw_oauth_json(['error'=>'server_error','debug'=>['class'=>get_class($e),'file'=>basename($e->getFile()),'line'=>$e->getLine()]],503);robw_oauth_error('server_error',503);}
}
function robw_oauth_authorize_error($error,$params,$redirect){$values=['error'=>$error];if(isset($params['state']))$values['state']=$params['state'];wp_redirect(add_query_arg($values,$redirect));exit;}
function robw_oauth_authorize(){if(!is_user_logged_in()){wp_redirect(wp_login_url(home_url($_SERVER['REQUEST_URI'])));exit;}$uid=get_current_user_id();if(!current_user_can('read'))robw_oauth_error('access_denied',403);$store=new RobwOAuthStore();$server=robw_oauth_server($store);$params=$_GET;
 if($_SERVER['REQUEST_METHOD']==='POST'){if($_GET)robw_oauth_error('invalid_request');$ticket=$_POST['ticket']??'';if(!wp_verify_nonce($_POST['_wpnonce']??'','robw-oauth-'.$ticket))robw_oauth_error('access_denied',403);$params=RobwOAuthDB::mutate(function(&$s)use($ticket,$uid){$key=RobwOAuthDB::key($ticket);$t=$s['tickets'][$key]??null;if(!$t||$t['uid']!==$uid||$t['expires']<=time())throw new InvalidArgumentException('Invalid consent');unset($s['tickets'][$key]);return $t['params'];});}elseif($_SERVER['REQUEST_METHOD']!=='GET')robw_oauth_error('invalid_request',405);
 $client=$params['client_id']??'';[$raw,$s]=RobwOAuthDB::read();$c=$s['clients'][$client]??null;$redirect=$params['redirect_uri']??'';if(!$c||!robw_oauth_redirect_matches($c['redirect_uri'],$redirect))robw_oauth_error('invalid_request');if(($params['response_type']??'')!=='code')robw_oauth_authorize_error('unsupported_response_type',$params,$redirect);if(($params['code_challenge_method']??'')!=='S256'||!preg_match('/^[A-Za-z0-9_-]{43}$/D',$params['code_challenge']??'')||strlen($params['state']??'')<1||strlen($params['state']??'')>256)robw_oauth_authorize_error('invalid_request',$params,$redirect);if(!$store->scopeExists($params['scope']??'')||array_diff(explode(' ',$params['scope']),explode(' ',$c['scope']))){$location=add_query_arg(['error'=>'invalid_scope','state'=>$params['state']],$redirect);wp_redirect($location);exit;}$store->pkce=['challenge'=>$params['code_challenge']];$store->redirectOverride[$client]=$redirect;$req=new RobwOAuthVendor\OAuth2\Request($params,[],[],[],[],['REQUEST_METHOD'=>'GET']);$res=new RobwOAuthVendor\OAuth2\Response();if(!$server->validateAuthorizeRequest($req,$res)){$res->send();exit;}
 if($_SERVER['REQUEST_METHOD']==='POST'){$server->handleAuthorizeRequest($req,$res,($_POST['decision']??'')==='approve',$uid);$res->send();exit;}
 $ticket=RobwOAuthDB::secret();RobwOAuthDB::mutate(function(&$s)use($ticket,$params,$uid){foreach($s['tickets']as$k=>$t)if($t['expires']<=time())unset($s['tickets'][$k]);if(count($s['tickets'])>=1000)throw new RuntimeException('Consent capacity');$s['tickets'][RobwOAuthDB::key($ticket)]=['uid'=>$uid,'params'=>$params,'expires'=>time()+300];});$parts=wp_parse_url($redirect);$origin=$parts['scheme'].'://'.$parts['host'].(isset($parts['port'])?':'.$parts['port']:'');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; form-action 'self' $origin; frame-ancestors 'none'; base-uri 'none'");header('Content-Type: text/html; charset=utf-8');echo '<!doctype html><title>Authorize Git access</title><h1>Authorize '.esc_html($c['name']).'</h1><p>Permissions: '.esc_html($params['scope']??'').'</p><p>This client receives access only where your account has repository permission.</p><form method="post" action="'.esc_url(home_url('/robw-oauth/authorize')).'"><input type="hidden" name="ticket" value="'.esc_attr($ticket).'">';wp_nonce_field('robw-oauth-'.$ticket);echo '<button name="decision" value="approve">Authorize</button><button name="decision" value="deny">Deny</button></form>';exit;}
function robw_oauth_admin(){if(!current_user_can('manage_options'))return;if($_SERVER['REQUEST_METHOD']==='POST'){check_admin_referer('robw-oauth-admin');$id=sanitize_key($_POST['client_id']??'');$uri=trim(wp_unslash($_POST['redirect_uri']??''));$parts=wp_parse_url($uri);$valid=$parts&&empty($parts['fragment'])&&empty($parts['user'])&&empty($parts['pass'])&&(($parts['scheme']??'')==='https'||(($parts['scheme']??'')==='http'&&in_array($parts['host']??'',['127.0.0.1','[::1]'],true)));if($id&&($_POST['operation']??'')==='delete'){RobwOAuthDB::mutate(function(&$s)use($id){unset($s['clients'][$id]);foreach($s['families']as$k=>$f)if(($f['client_id']??null)===$id)$s['families'][$k]['revoked']=true;});}elseif($id&&$valid){$name=sanitize_text_field($_POST['client_name']??'');$scope=isset($_POST['write'])?'repo:read repo:write':'repo:read';RobwOAuthDB::mutate(function(&$s)use($id,$uri,$name,$scope){$s['clients'][$id]=['name'=>$name,'redirect_uri'=>$uri,'scope'=>$scope];});}else echo '<div class="notice notice-error">Invalid client</div>';}
 echo '<div class="wrap"><h1>Git OAuth clients</h1><p>Public clients: no shared secret. PKCE-S256 is mandatory. Register an exact HTTPS callback or loopback IP callback.</p><form method="post">';wp_nonce_field('robw-oauth-admin');echo '<p><label>Client ID <input name="client_id" required></label></p><p><label>Name <input name="client_name"></label></p><p><label>Redirect URI <input name="redirect_uri" type="url"></label></p><p><label><input type="checkbox" name="write"> Allow repository write scope</label></p><button name="operation" value="save">Save client</button><button name="operation" value="delete">Delete client</button></form>';[$raw,$s]=RobwOAuthDB::read();echo '<ul>';foreach($s['clients']as$id=>$c)echo '<li>'.esc_html($id.' — '.$c['name'].' — '.$c['redirect_uri'].' — '.$c['scope']).'</li>';echo '</ul></div>';}
